"""Create a dependency-free PowerPoint for the CampusOS six-phase seminar."""
from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED
from xml.sax.saxutils import escape

OUT = Path(__file__).resolve().parents[1] / "docs" / "seminar" / "project-lifecycle-six-phases.pptx"
OUT.parent.mkdir(parents=True, exist_ok=True)
W, H = 12192000, 6858000
slides = [
 ("PROJECT LIFECYCLE", "SIX PHASES", ["A practical guide from idea to measurable outcomes", "Campus Placement Portal · Academic seminar"], "A clear path from campus need to better placement outcomes"),
 ("Why a lifecycle?", "A shared path turns an idea into a dependable service.", ["Create alignment on the problem and the people affected", "Plan scope, time, resources and risks", "Deliver, learn and check whether benefits arrived"], "Each phase creates a checkpoint for informed decisions."),
 ("Six phases at a glance", "INITIATE → PLAN → EXECUTE ↔ MONITOR → CLOSE → REVIEW", ["Initiation defines why and for whom", "Planning maps scope, people, time and risks", "Monitoring runs alongside execution", "Benefits review follows delivery"], "The six-phase order is the seminar's selected framework."),
 ("01 · Project Initiation", "Agree on the need before choosing a solution.", ["Identify fragmented placement communication", "Set goals: one source for roles, applications and updates", "Name stakeholders: students, recruiters, TPO and faculty", "Check feasibility and record initial scope in a charter"], "Portal example: replace scattered spreadsheets and messages."),
 ("02 · Project Planning", "Turn stakeholder needs into an achievable plan.", ["Gather requirements for all three roles", "Build a work breakdown and sequence dependencies", "Estimate people, time, cost and quality needs", "Plan risks, communication and Jira sprints"], "Portal example: prioritize auth, profiles, roles, applications and interviews."),
 ("03 · Project Execution", "Coordinate people and build accepted deliverables.", ["Assign work and keep communication visible", "Develop interfaces, APIs and data relationships", "Review code and validate workflows during delivery", "Share increments with stakeholders for feedback"], "Portal example: build role-based experiences in small increments."),
 ("04 · Monitoring & Controlling", "Observe actual progress and act on deviations.", ["Compare completed work with sprint plan", "Watch scope, schedule, quality and project risks", "Resolve blockers and record decisions", "Use evidence to adjust the next plan"], "Monitoring happens throughout execution, not only at the end."),
 ("The monitoring loop", "A feedback loop keeps delivery aligned.", ["PLAN → EXECUTE → MONITOR", "COMPARE ACTUAL WITH PLAN → IDENTIFY DEVIATION", "TAKE CORRECTIVE ACTION → UPDATE PLAN", "CONTINUE EXECUTION AND REPEAT"], "Jira board: To Do → In Progress → Done, reviewed every sprint."),
 ("05 · Project Closure", "Confirm the result is ready to hand over.", ["Run final workflow and security checks", "Obtain stakeholder acceptance against scope", "Deliver documentation, support notes and training", "Record lessons and close outstanding work clearly"], "Portal example: demonstrate student, recruiter and TPO journeys."),
 ("06 · Benefits Realization", "Check whether the change made a useful difference.", ["Measure student participation and application follow-through", "Compare coordination time with the prior process", "Collect student, recruiter and TPO feedback", "Prioritize maintenance and future improvements"], "Benefits review may sit inside closure or post-project governance."),
 ("One portal · six phases", "A continuous thread connects the project phases.", ["Initiate: identify manual coordination pain", "Plan: turn needs into roles, stories and two sprints", "Execute & monitor: build, review, test and re-plan", "Close & review: accept delivery and measure outcomes"], "One goal guides decisions from charter through post-launch review."),
 ("Challenges & lessons", "Plan for adoption, safety and change.", ["Data quality needs ownership and validation", "Student records require access controls and secure storage", "Integration and testing often take longer than expected", "Early feedback prevents late interface rework"], "Keep scope small enough to validate meaningful workflows."),
 ("Conclusion", "A lifecycle makes delivery visible and accountable.", ["Initiate with a clear need", "Plan with people, scope and risks in view", "Execute while monitoring continuously", "Close responsibly and measure benefits"], "Thank you · Campus Placement Portal"),
 ("Questions & Answers", "Thank you for listening.", ["Questions?", "Member 1 · Introduction and Initiation", "Member 2 · Planning and Execution", "Member 3 · Monitoring and Controlling", "Member 4 · Closure and Benefits"], "Editable team names and slide ownership are in the seminar notes."),
]

def shape(sid, name, x, y, w, h, text=None, fill=None, color="202235", size=1800, bold=False, font="Aptos"):
    nv=f'<p:nvSpPr><p:cNvPr id="{sid}" name="{escape(name)}"/><p:cNvSpPr/><p:nvPr/></p:nvSpPr>'
    xfrm=f'<a:xfrm><a:off x="{x}" y="{y}"/><a:ext cx="{w}" cy="{h}"/></a:xfrm>'
    fill_xml=f'<a:solidFill><a:srgbClr val="{fill}"/></a:solidFill>' if fill else '<a:noFill/>'
    sppr=f'<p:spPr>{xfrm}<a:prstGeom prst="rect"><a:avLst/></a:prstGeom>{fill_xml}<a:ln><a:noFill/></a:ln></p:spPr>'
    if text is None: return f'<p:sp>{nv}{sppr}<p:txBody><a:bodyPr/><a:lstStyle/><a:p/></p:txBody></p:sp>'
    paragraphs=[]
    for line in text:
        paragraphs.append(f'<a:p><a:pPr/><a:r><a:rPr lang="en-US" sz="{size}" b="{1 if bold else 0}"><a:solidFill><a:srgbClr val="{color}"/></a:solidFill><a:latin typeface="{font}"/></a:rPr><a:t>{escape(line)}</a:t></a:r><a:endParaRPr lang="en-US" sz="{size}"/></a:p>')
    tx=f'<p:txBody><a:bodyPr wrap="square" lIns="180000" rIns="180000" tIns="120000" bIns="120000" anchor="ctr"/><a:lstStyle/>{"".join(paragraphs)}</p:txBody>'
    return f'<p:sp>{nv}{sppr}{tx}</p:sp>'

def slide_xml(index, item):
    title, lead, bullets, callout=item
    bg=shape(2,"Background",0,0,W,H,fill="F7F7FB")
    bar=shape(3,"Top accent",0,0,W,150000,fill="7060D9")
    label=shape(4,"Slide number",650000,420000,1200000,400000,[f"{index:02d} / 14"],color="7060D9",size=1100,bold=True)
    heading=shape(5,"Title",650000,900000,10800000,1000000,[title],color="202235",size=3000,bold=True)
    leadshape=shape(6,"Lead",650000,1850000,10800000,950000,[lead],color="5749B7",size=2100,bold=True)
    card=shape(7,"Content card",650000,3000000,10800000,2300000,fill="FFFFFF")
    body=shape(8,"Key points",850000,3150000,10400000,1950000,["•  "+x for x in bullets],color="50536A",size=1600)
    foot=shape(9,"Campus example",650000,5600000,10800000,620000,[callout],color="FFFFFF",size=1300,bold=True,fill="282743")
    tree='<p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr>'+bg+bar+label+heading+leadshape+card+body+foot+'</p:spTree>'
    return f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><p:sld xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"><p:cSld>{tree}</p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>'

content_types=['<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>','<Default Extension="xml" ContentType="application/xml"/>','<Override PartName="/ppt/presentation.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml"/>','<Override PartName="/ppt/slideMasters/slideMaster1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideMaster+xml"/>','<Override PartName="/ppt/slideLayouts/slideLayout1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideLayout+xml"/>','<Override PartName="/ppt/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>']+[f'<Override PartName="/ppt/slides/slide{i}.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slide+xml"/>' for i in range(1,len(slides)+1)]
root_rels='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="ppt/presentation.xml"/></Relationships>'
pres_ids=''.join(f'<p:sldId id="{255+i}" r:id="rId{i+1}"/>' for i in range(1,len(slides)+1))
pres_rels='<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" Target="slideMasters/slideMaster1.xml"/>'+''.join(f'<Relationship Id="rId{i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide" Target="slides/slide{i}.xml"/>' for i in range(1,len(slides)+1))
presentation=f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><p:presentation xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"><p:sldMasterIdLst><p:sldMasterId id="2147483648" r:id="rId1"/></p:sldMasterIdLst><p:sldIdLst>{pres_ids}</p:sldIdLst><p:sldSz cx="{W}" cy="{H}" type="wide"/><p:notesSz cx="6858000" cy="9144000"/><p:defaultTextStyle/></p:presentation>'
theme='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><a:theme xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" name="CampusOS"><a:themeElements><a:clrScheme name="CampusOS"><a:dk1><a:srgbClr val="202235"/></a:dk1><a:lt1><a:srgbClr val="FFFFFF"/></a:lt1><a:dk2><a:srgbClr val="282743"/></a:dk2><a:lt2><a:srgbClr val="F7F7FB"/></a:lt2><a:accent1><a:srgbClr val="7060D9"/></a:accent1><a:accent2><a:srgbClr val="43A889"/></a:accent2><a:accent3><a:srgbClr val="FF9A69"/></a:accent3><a:accent4><a:srgbClr val="5488DC"/></a:accent4><a:accent5><a:srgbClr val="E5F6EE"/></a:accent5><a:accent6><a:srgbClr val="FFF0E7"/></a:accent6><a:hlink><a:srgbClr val="5948C5"/></a:hlink><a:folHlink><a:srgbClr val="7865ED"/></a:folHlink></a:clrScheme><a:fontScheme name="CampusOS"><a:majorFont><a:latin typeface="Aptos Display"/></a:majorFont><a:minorFont><a:latin typeface="Aptos"/></a:minorFont></a:fontScheme><a:fmtScheme name="CampusOS"><a:fillStyleLst><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:fillStyleLst><a:lnStyleLst><a:ln w="6350"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:ln></a:lnStyleLst><a:effectStyleLst><a:effectStyle><a:effectLst/></a:effectStyle></a:effectStyleLst><a:bgFillStyleLst><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:bgFillStyleLst></a:fmtScheme></a:themeElements></a:theme>'
master=f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><p:sldMaster xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"><p:cSld><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr></p:spTree></p:cSld><p:clrMap bg1="lt1" tx1="dk1" bg2="lt2" tx2="dk2" accent1="accent1" accent2="accent2" accent3="accent3" accent4="accent4" accent5="accent5" accent6="accent6" hlink="hlink" folHlink="folHlink"/><p:sldLayoutIdLst><p:sldLayoutId id="1" r:id="rId1"/></p:sldLayoutIdLst><p:txStyles><p:titleStyle/><p:bodyStyle/><p:otherStyle/></p:txStyles></p:sldMaster>'
layout='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><p:sldLayout xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" type="blank" preserve="1"><p:cSld name="Blank"><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr></p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sldLayout>'

with ZipFile(OUT,"w",ZIP_DEFLATED) as z:
    z.writestr("[Content_Types].xml",'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'+''.join(content_types)+'</Types>')
    z.writestr("_rels/.rels",root_rels);z.writestr("ppt/presentation.xml",presentation);z.writestr("ppt/_rels/presentation.xml.rels",f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">{pres_rels}</Relationships>')
    z.writestr("ppt/theme/theme1.xml",theme);z.writestr("ppt/slideMasters/slideMaster1.xml",master);z.writestr("ppt/slideMasters/_rels/slideMaster1.xml.rels",'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" Target="../theme/theme1.xml"/></Relationships>')
    z.writestr("ppt/slideLayouts/slideLayout1.xml",layout);z.writestr("ppt/slideLayouts/_rels/slideLayout1.xml.rels",'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" Target="../slideMasters/slideMaster1.xml"/></Relationships>')
    for i,item in enumerate(slides,1):z.writestr(f"ppt/slides/slide{i}.xml",slide_xml(i,item));z.writestr(f"ppt/slides/_rels/slide{i}.xml.rels",'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/></Relationships>')
print(OUT)
